private string Value(string title, string employer, string location, string arrangement, string description, string payMin, string payMax, string skillsRequired, string skillsMissing, string setting1, string setting2, string setting3)
{
    var lines = skillsMissing.Split('\n');
    var sb = new StringBuilder();
    var count = 0;
    for (var i = 0; i < lines.Length; i++)
    {
        var skill = lines[i].Trim();
        if (skill.Length == 0)
            continue;
        if (count > 0)
            sb.Append(", ");
        sb.Append(skill);
        count++;
    }
    if (count == 0)
        return "none";
    return sb.ToString();
}
